def transform_up_to_date(grid):
    """Transform based on detailed pattern analysis"""
    height = len(grid)
    width = len(grid[0])

    # Find 3 positions
    sources = []
    for r in range(height):
        for c in range(width):
            if grid[r][c] == 3:
                sources.append((r, c))

    result = [[0]*width for _ in range(height)]

    # Copy 3s to output
    for sr, sc in sources:
        result[sr][sc] = 3

    if len(sources) == 1:
        # Only one 3 - no patterns generated
        return result

    # Sort by row
    sources_sorted = sorted(sources)
    upper = sources_sorted[0]
    lower = sources_sorted[1]

    # Upper source patterns:
    # 1. 5s row at 2 rows above, extending RIGHT
    r_5s_upper = upper[0] - 2
    if 0 <= r_5s_upper < height:
        c_start = upper[1]
        # Extend right - use 5 cells
        c_end = min(c_start + 5, width)
        for c in range(c_start, c_end):
            result[r_5s_upper][c] = 5

    # 2. 2s at same row, dc = ±2
    for dc in [-2, 2]:
        r, c_u = upper[0], upper[1] + dc
        if 0 <= c_u < width:
            result[r][c_u] = 2

    # Lower source patterns:
    # 1. 2s at dc = ±2 for 4 consecutive rows starting at dr = -1
    for dr in [-1, 0, 1, 2]:
        r, c_l = lower[0] + dr, lower[1]
        if 0 <= c_l < width:
            result[r][c_l] = 3  # Just in case, clarify
            for dc in [-2, 2]:
                c = c_l + dc
                if 0 <= c < width:
                    result[r][c] = 2

    # 2. At dr = +3 (3 rows below): 8s centered on source
    r_8s = lower[0] + 3
    if 0 <= r_8s < height:
        # First put 8s at dc = -2, -1, 0, 1, 2
        for dc in [-2, -1, 0, 1, 2]:
            c = lower[1] + dc
            if 0 <= c < width:
                result[r_8s][c] = 8

        # Then put 2s everywhere else in that row
        for c in range(width):
            if result[r_8s][c] == 0:
                result[r_8s][c] = 2

    return result

