    sources = []
    for r in range(height):
        for c in range(width):
            if grid[r][c] == 3:
                sources.append((r, c))

    result = [[0]*width for _ in range(height)]

    # Copy 3s
    for sr, sc in sources:
        result[sr][sc] = 3

    if len(sources) < 2:
        return result

    # Sort by row
    sources_sorted = sorted(sources, key=lambda x: (x[0], x[1]))

    upper = sources_sorted[0]
    lower = sources_sorted[-1]

    # Upper source patterns (ONLY first source)
    # 1. 5s row at 2 rows above
    r_5s = upper[0] - 2
    if 0 <= r_5s < height:
        c_start = upper[1]
        c_end = min(c_start + 5, width)
        for c in range(c_start, c_end):
            result[r_5s][c] = 5

    # 2. 2s at same row, dc = ±2
    for dc in [-2, 2]:
        c_u = upper[1] + dc
        if 0 <= c_u < width:
            result[upper[0]][c_u] = 2

    # Lower source patterns (ONLY last source)
    # 1. Single 5 at 1 row above
    r_5_single = lower[0] - 1
    if 0 <= r_5_single < height:
        result[r_5_single][lower[1]] = 5

    # 2. 2s at dc = ±2 for 4 consecutive rows starting at dr = -1
    for dr in [-1, 0, 1, 2]:
        r = lower[0] + dr
        if 0 <= r < height:
            for dc in [-2, 2]:
                c = lower[1] + dc
                if 0 <= c < width:
                    result[r][c] = 2

    # 3. At dr = +3: 8s and rest 2s
    r_8s = lower[0] + 3
    if 0 <= r_8s < height:
        for dc in [-2, -1, 0, 1, 2]:
            c = lower[1] + dc
            if 0 <= c < width:
                result[r_8s][c] = 8
        for c in range(width):
            if result[r_8s][c] == 0:
                result[r_8s][c] = 2

    return result

